//! Build-time configuration generated by `build.rs` from
//! `gateway.local.toml` (gitignored) or the committed example.

include!(concat!(env!("OUT_DIR"), "/gateway_config.rs"));

/// Hologram APN.
pub const APN: &str = "hologram";

/// Firmware version packed as `major << 16 | minor << 8 | patch` for
/// `CheckIn.gw_fw`.
pub const FW_VERSION: u32 = {
    const fn parse(s: &str) -> u32 {
        let b = s.as_bytes();
        let mut i = 0;
        let mut v = 0u32;
        while i < b.len() {
            v = v * 10 + (b[i] - b'0') as u32;
            i += 1;
        }
        v
    }
    (parse(env!("CARGO_PKG_VERSION_MAJOR")) << 16)
        | (parse(env!("CARGO_PKG_VERSION_MINOR")) << 8)
        | parse(env!("CARGO_PKG_VERSION_PATCH"))
};
